-- Номер клиента, оплата по чеку (статус review), тестовые карты
alter table public.profiles add column if not exists user_no bigint generated by default as identity;
create unique index if not exists profiles_user_no_idx on public.profiles(user_no);
alter table public.orders drop constraint if exists orders_status_check;
alter table public.orders add constraint orders_status_check check (status in ('new','review','paid','bought','shipping','arrived','delivered','cancelled'));
alter table public.orders add column if not exists pay_card text, add column if not exists receipt_path text, add column if not exists receipt_at timestamptz, add column if not exists reject_reason text;
alter table public.admin_messages drop constraint if exists admin_messages_kind_check;
alter table public.admin_messages add constraint admin_messages_kind_check check (kind in ('order','photo','receipt'));
insert into public.settings (key, value) values ('payment_cards', '["8600 0000 0000 0001","8600 0000 0000 0002","9860 0000 0000 0003"]') on conflict (key) do nothing;
